import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Category-Label-Positions.md","filePath":"manual-en/CTABLES-Category-Label-Positions.md","lastUpdated":1785684581000}'),a={name:"manual-en/CTABLES-Category-Label-Positions.md"};function l(i,t,n,h,s,c){return e(),o("div",null,[...t[0]||(t[0]=[r(`<h4 id="_15-7-4-category-label-positions" tabindex="-1">15.7.4 Category Label Positions <a class="header-anchor" href="#_15-7-4-category-label-positions" aria-label="Permalink to &quot;15.7.4 Category Label Positions&quot;">​</a></h4><pre><code>/CLABELS {AUTO _|_ {ROWLABELS _|_ COLLABELS}={OPPOSITE _|_ LAYER}}
</code></pre><p>The <code>CLABELS</code> subcommand controls the position of category labels for the <code>TABLE</code> subcommand that it follows. By default, or if <code>AUTO</code> is specified, category labels for a given variable nest inside the variable’s label on the same axis. For example, the command below results in age categories nesting within the age group variable on the rows axis and gender categories within the gender variable on the columns axis:</p><pre><code>CTABLES /TABLE ageGroup BY gender.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Male</th><th>Female</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td></tr><tr><td></td><td></td><td>Count</td><td>Count</td></tr><tr><td>Age group</td><td>15 or younger</td><td>0</td><td>0</td></tr><tr><td>16 to 25</td><td>594</td><td>505</td><td></td></tr><tr><td>26 to 35</td><td>476</td><td>491</td><td></td></tr><tr><td>36 to 45</td><td>489</td><td>548</td><td></td></tr><tr><td>46 to 55</td><td>526</td><td>649</td><td></td></tr><tr><td>56 to 65</td><td>516</td><td>731</td><td></td></tr><tr><td>66 or older</td><td>531</td><td>943</td><td></td></tr></tbody></table><p><code>ROWLABELS=OPPOSITE</code> or <code>COLLABELS=OPPOSITE</code> move row or column variable category labels, respectively, to the opposite axis. The setting affects only the innermost variable or variables, which must be categorical, on the given axis. For example:</p><pre><code>CTABLES /TABLE ageGroup BY gender /CLABELS ROWLABELS=OPPOSITE.
CTABLES /TABLE ageGroup BY gender /CLABELS COLLABELS=OPPOSITE.
</code></pre><table tabindex="0"><thead><tr><th></th><th>15 or younger</th><th>16 to 25</th><th>26 to 35</th><th>36 to 45</th><th>46 to 55</th><th>56 to 65</th><th>66 or older</th><th>15 or younger</th><th>16 to 25</th><th>26 to 35</th><th>36 to 45</th><th>46 to 55</th><th>56 to 65</th><th>66 or older</th></tr></thead><tbody><tr><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Male</td><td>Female</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td><td>Count</td></tr><tr><td>Age group</td><td>0</td><td>594</td><td>476</td><td>489</td><td>526</td><td>516</td><td>531</td><td>0</td><td>505</td><td>491</td><td>548</td><td>649</td><td>731</td><td>943</td></tr><tr><td></td><td></td><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td>Count</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Age group</td><td>15 or younger</td><td>Male</td><td>0</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>0</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>16 to 25</td><td>Male</td><td>594</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>505</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>26 to 35</td><td>Male</td><td>476</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>491</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>36 to 45</td><td>Male</td><td>489</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>548</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>46 to 55</td><td>Male</td><td>526</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>649</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>56 to 65</td><td>Male</td><td>516</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>731</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>66 or older</td><td>Male</td><td>531</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>943</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><code>ROWLABELS=LAYER</code> or <code>COLLABELS=LAYER</code> move the innermost row or column variable category labels, respectively, to the layer axis.</p><p>Only one axis’s labels may be moved, whether to the opposite axis or to the layer axis.</p><h4 id="effect-on-summary-statistics" tabindex="-1">Effect on Summary Statistics <a class="header-anchor" href="#effect-on-summary-statistics" aria-label="Permalink to &quot;Effect on Summary Statistics&quot;">​</a></h4><p><code>CLABELS</code> primarily affects the appearance of tables, not the data displayed in them. However, <code>CTABLES</code> can affect the values displayed for statistics that summarize areas of a table, since it can change the definitions of these areas.</p><p>For example, consider the following syntax and output:</p><pre><code>CTABLES /TABLE ageGroup BY gender [ROWPCT, COLPCT].
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Row %</th><th>Column %</th><th>Row %</th><th>Column %</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>Male</td><td>Female</td><td></td><td></td></tr><tr><td>Age group</td><td>15 or younger</td><td>.</td><td>.0%</td><td>.</td><td>.0%</td></tr><tr><td>16 to 25</td><td>54.0%</td><td>19.0%</td><td>46.0%</td><td>13.1%</td><td></td></tr><tr><td>26 to 35</td><td>49.2%</td><td>15.2%</td><td>50.8%</td><td>12.7%</td><td></td></tr><tr><td>36 to 45</td><td>47.2%</td><td>15.6%</td><td>52.8%</td><td>14.2%</td><td></td></tr><tr><td>46 to 55</td><td>44.8%</td><td>16.8%</td><td>55.2%</td><td>16.8%</td><td></td></tr><tr><td>56 to 65</td><td>41.4%</td><td>16.5%</td><td>58.6%</td><td>18.9%</td><td></td></tr><tr><td>66 or older</td><td>36.0%</td><td>17.0%</td><td>64.0%</td><td>24.4%</td><td></td></tr></tbody></table><p>Using <code>COLLABELS=OPPOSITE</code> changes the definitions of rows and columns, so that column percentages display what were previously row percentages and the new row percentages become meaningless (because there is only one cell per row):</p><pre><code>CTABLES
    /TABLE ageGroup BY gender [ROWPCT, COLPCT]
    /CLABELS COLLABELS=OPPOSITE.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th>Row %</th><th>Column %</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>S3a. GENDER:</td><td></td></tr><tr><td>Age group</td><td>15 or younger</td><td>Male</td><td>.</td><td>.</td></tr><tr><td>Female</td><td>.</td><td>.</td><td></td><td></td></tr><tr><td>16 to 25</td><td>Male</td><td>100.0%</td><td>54.0%</td><td></td></tr><tr><td>Female</td><td>100.0%</td><td>46.0%</td><td></td><td></td></tr><tr><td>26 to 35</td><td>Male</td><td>100.0%</td><td>49.2%</td><td></td></tr><tr><td>Female</td><td>100.0%</td><td>50.8%</td><td></td><td></td></tr><tr><td>36 to 45</td><td>Male</td><td>100.0%</td><td>47.2%</td><td></td></tr><tr><td>Female</td><td>100.0%</td><td>52.8%</td><td></td><td></td></tr><tr><td>46 to 55</td><td>Male</td><td>100.0%</td><td>44.8%</td><td></td></tr><tr><td>Female</td><td>100.0%</td><td>55.2%</td><td></td><td></td></tr><tr><td>56 to 65</td><td>Male</td><td>100.0%</td><td>41.4%</td><td></td></tr><tr><td>Female</td><td>100.0%</td><td>58.6%</td><td></td><td></td></tr><tr><td>66 or older</td><td>Male</td><td>100.0%</td><td>36.0%</td><td></td></tr><tr><td>Female</td><td>100.0%</td><td>64.0%</td><td></td><td></td></tr></tbody></table><h4 id="moving-categories-for-stacked-variables" tabindex="-1">Moving Categories for Stacked Variables <a class="header-anchor" href="#moving-categories-for-stacked-variables" aria-label="Permalink to &quot;Moving Categories for Stacked Variables&quot;">​</a></h4><p>If <code>CLABELS</code> moves category labels from an axis with stacked variables, the variables that are moved must have the same category specifications (see <a href="./CTABLES-Per_002dVariable-Category-Options">CTABLES Per-Variable Category Options</a>) and the same value labels.</p><p>The following shows both moving stacked category variables and adapting to the changing definitions of rows and columns:</p><pre><code>CTABLES /TABLE (likelihoodOfBeingStoppedByPolice
                + likelihoodOfHavingAnAccident) [COLPCT].
CTABLES /TABLE (likelihoodOfBeingStoppedByPolice
                + likelihoodOfHavingAnAccident) [ROWPCT]
  /CLABELS ROW=OPPOSITE.
</code></pre><table tabindex="0"><thead><tr><th></th><th>Almost certain</th><th>Very likely</th><th>Somewhat likely</th><th>Somewhat unlikely</th><th>Very unlikely</th></tr></thead><tbody><tr><td></td><td></td><td>Column %</td><td></td><td></td><td></td></tr><tr><td>105b. How likely is it that drivers who have had too much to drink to drive safely will A. Get stopped by the police?</td><td>Almost certain</td><td>10.2%</td><td></td><td></td><td></td></tr><tr><td>Very likely</td><td>21.8%</td><td></td><td></td><td></td><td></td></tr><tr><td>Somewhat likely</td><td>40.2%</td><td></td><td></td><td></td><td></td></tr><tr><td>Somewhat unlikely</td><td>19.0%</td><td></td><td></td><td></td><td></td></tr><tr><td>Very unlikely</td><td>8.9%</td><td></td><td></td><td></td><td></td></tr><tr><td>105b. How likely is it that drivers who have had too much to drink to drive safely will B. Have an accident?</td><td>Almost certain</td><td>15.9%</td><td></td><td></td><td></td></tr><tr><td>Very likely</td><td>40.8%</td><td></td><td></td><td></td><td></td></tr><tr><td>Somewhat likely</td><td>35.0%</td><td></td><td></td><td></td><td></td></tr><tr><td>Somewhat unlikely</td><td>6.2%</td><td></td><td></td><td></td><td></td></tr><tr><td>Very unlikely</td><td>2.0%</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Row %</td><td>Row %</td><td>Row %</td><td>Row %</td><td>Row %</td></tr><tr><td>105b. How likely is it that drivers who have had too much to drink to drive safely will A. Get stopped by the police?</td><td>10.2%</td><td>21.8%</td><td>40.2%</td><td>19.0%</td><td>8.9%</td></tr><tr><td>105b. How likely is it that drivers who have had too much to drink to drive safely will B. Have an accident?</td><td>15.9%</td><td>40.8%</td><td>35.0%</td><td>6.2%</td><td>2.0%</td></tr></tbody></table>`,23)])])}const u=d(a,[["render",l]]);export{p as __pageData,u as default};
